// intent: Exercise ordered_json parsing with nested objects containing many keys at multiple levels to ensure key_indexes insertions occur recursively.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>

int main() {
    try {
        std::string s = "{";
        for (int i = 0; i < 64; ++i) {
            if (i > 0) s += ",";
            s += "\"outer" + std::to_string(i) + "\":{";
            for (int k = 0; k < 64; ++k) {
                if (k > 0) s += ",";
                s += "\"inner" + std::to_string(k) + "\":" + std::to_string(k);
            }
            s += "}";
        }
        s += "}";
        auto j = nlohmann::ordered_json::parse(s);
        std::cout << "nested ordered_json size: " << j.size() << std::endl;
        std::cout << "nested value: " << j["outer10"]["inner20"] << std::endl;
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << std::endl;
    }
    return 0;
}
